test:
let mut g = Life::new(5,5); g.set(1,2,true); g.set(2,2,true); g.set(3,2,true);
    g.step();
    assert!(g.get(2,1) && g.get(2,2) && g.get(2,3) && !g.get(1,2) && !g.get(3,2));
    g.step();
    assert!(g.get(1,2) && g.get(2,2) && g.get(3,2));
    let mut b = Life::new(4,4); b.set(1,1,true); b.set(2,1,true); b.set(1,2,true); b.set(2,2,true);
    b.step();
    assert_eq!(b.population(), 4);
    let mut s = Life::new(3,3); s.set(1,1,true); s.step(); assert_eq!(s.population(), 0);

assert_eq!(merge_left(&[2,2,2,2]), vec![4,4,0,0]);
    assert_eq!(merge_left(&[2,0,2,4]), vec![4,4,0,0]);
    assert_eq!(merge_left(&[4,4,8,0]), vec![8,8,0,0]);
    assert_eq!(merge_left(&[0,0,0,2]), vec![2,0,0,0]);

let mut b = vec![vec!['.';5];5]; for i in 0..4 { b[i][1]='R'; }
    assert!(connect4_win(&b,'R'));
    assert!(!connect4_win(&b,'Y'));
    let mut d = vec![vec!['.';5];5]; for i in 0..4 { d[i][i]='Y'; }
    assert!(connect4_win(&d,'Y'));

assert_eq!(knight_moves(0,0), vec![(1,2),(2,1)]);
    assert_eq!(knight_moves(4,4).len(), 8);
    let mut m = knight_moves(7,7); m.sort();
    assert_eq!(m, vec![(5,6),(6,5)]);

let mines = vec![vec![true,false,false],vec![false,false,false],vec![false,false,true]];
    let mc = mine_counts(&mines);
    assert_eq!(mc[0][0],9); assert_eq!(mc[0][1],1); assert_eq!(mc[1][1],2); assert_eq!(mc[2][2],9); assert_eq!(mc[0][2],0);
